script:
(function () {
  'use strict';
  // Early payoff of an existing mortgage from its current balance.
  //   Current P&I payment: given, or P = B * i / (1 - (1 + i)^-n) from the remaining term (P = B / n at 0%).
  //   Each month: interest = balance * i; principal = P - interest + extra monthly
  //   (+ extra yearly with every 12th payment); a one-time lump sum is applied before the first payment.
  //   Payment needed to finish in T months: payment(B, i, T); extra needed = that - P.
  // Verified in Node (scratchpad tests/m5): $250,000 at 6.5% over 25 yrs = $1,688.02/mo, remaining
  //   interest $256,405.37 (closed form); with $200 extra the payoff month count equals
  //   ceil(-ln(1 - B*i/(P+X)) / ln(1+i)); a known payment of $1,688.02 gives back the same 300-month payoff;
  //   the extra needed to finish in 15 yrs ($489.76, rounded up to the cent), entered as the extra
  //   monthly amount, pays the loan off in exactly 180 months;
  //   payment below the monthly interest is rejected; 0% rate works; no NaN/Infinity on blank input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var MAX_MONTHS = 1200;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function paymentFor(balance, i, n) {
    if (n <= 0 || balance <= 0) return 0;
    if (i === 0) return balance / n;
    return balance * i / (1 - Math.pow(1 + i, -n));
  }

  // Returns month-by-month balances, total interest and the number of payments.
  function simulate(balance, i, pay, extraMonthly, extraYearly) {
    var bal = balance, interest = 0, balances = [], extraPaid = 0;
    for (var m = 1; m <= MAX_MONTHS && bal > 0.005; m++) {
      var intr = bal * i;
      var principal = Math.min(pay - intr, bal);
      var extra = extraMonthly + (m % 12 === 0 ? extraYearly : 0);
      extra = Math.max(0, Math.min(extra, bal - principal));
      bal -= principal + extra;
      if (bal < 0.005) bal = 0;
      interest += intr;
      extraPaid += extra;
      balances.push(bal);
    }
    return { months: balances.length, interest: interest, balances: balances, extraPaid: extraPaid };
  }

  function monthLabel(start, offset) {
    var t = start + offset;
    return MONTHS[t % 12] + ' ' + Math.floor(t / 12);
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    ['mpPI', 'mpNewDate', 'mpTimeSaved', 'mpInterestSaved', 'mpOldDate', 'mpOldInterest', 'mpNewInterest',
     'mpExtraTotal', 'mpGoalText'].forEach(function (id) { setText(id, '–'); });
    el('mpGoal').hidden = true;
    el('mpYears').innerHTML = '';
  }

  function update() {
    var mode = el('mpMode').value;
    el('mpTermWrap').hidden = mode !== 'term';
    el('mpPaymentWrap').hidden = mode === 'term';
    var balance = read('mpBalance'), rate = read('mpRate'), remY = read('mpRemYears', true),
        remM = read('mpRemMonths', true), knownPay = read('mpPayment'),
        exM = read('mpExtraMonthly', true), exY = read('mpExtraYearly', true), lump = read('mpLump', true),
        target = read('mpTarget', true);
    var i = rate / 100 / 12, remaining = remY * 12 + remM;
    var error = el('mpError'), msg = '';
    if (isNaN(balance) || balance <= 0) msg = 'Enter a remaining loan balance greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (mode === 'term' && (isNaN(remY) || isNaN(remM) || remY < 0 || remM < 0 || remM > 11 || remY % 1 !== 0 || remM % 1 !== 0 || remaining < 1 || remaining > 600))
      msg = 'Enter a remaining term from 1 month to 50 years (whole years and 0 to 11 months).';
    else if (mode !== 'term' && (isNaN(knownPay) || knownPay <= 0)) msg = 'Enter your monthly principal and interest payment.';
    else if (mode !== 'term' && knownPay <= balance * i) msg = 'That payment does not cover the monthly interest of ' + money.format(balance * i) + ', so the loan would never be repaid.';
    else if ([exM, exY, lump, target].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Extra payments and the target cannot be negative.';
    else if (target > 50) msg = 'Enter a target of 50 years or less, or leave it blank.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var pay = mode === 'term' ? paymentFor(balance, i, remaining) : knownPay;
    var base = simulate(balance, i, pay, 0, 0);
    var afterLump = Math.max(0, balance - lump);
    var plan = simulate(afterLump, i, pay, exM, exY);
    var now = new Date(), start = now.getFullYear() * 12 + now.getMonth() + 1;

    setText('mpPI', money.format(pay));
    setText('mpOldDate', base.months ? monthLabel(start, base.months - 1) : 'Paid off');
    setText('mpNewDate', plan.months ? monthLabel(start, plan.months - 1) : 'Paid off now');
    setText('mpTimeSaved', duration(Math.max(0, base.months - plan.months)));
    setText('mpInterestSaved', money.format(Math.max(0, base.interest - plan.interest)));
    setText('mpOldInterest', money.format(base.interest));
    setText('mpNewInterest', money.format(plan.interest));
    setText('mpExtraTotal', money.format(Math.min(lump, balance) + plan.extraPaid));

    var goal = el('mpGoal');
    if (target > 0) {
      var tMonths = Math.max(1, Math.round(target * 12));
      var needed = paymentFor(afterLump, i, tMonths), extraNeeded = Math.ceil((needed - pay) * 100 - 1e-6) / 100;
      needed = pay + extraNeeded; // round the extra up to the cent so entering it meets the target
      var text;
      if (afterLump <= 0) text = 'The lump sum pays the loan off now.';
      else if (extraNeeded <= 0.005) text = 'Your regular payment' + (lump > 0 ? ', after the lump sum,' : '') + ' already clears the loan within ' + duration(tMonths) + '.';
      else text = 'To be debt-free in ' + duration(tMonths) + ', pay ' + money.format(needed) + ' a month: ' +
        money.format(extraNeeded) + ' more than your current payment' + (lump > 0 ? ', after the lump sum' : '') + '.' +
        (exM > 0 || exY > 0 ? ' This replaces the extra monthly and yearly amounts above.' : '');
      setText('mpGoalText', text);
      goal.hidden = false;
    } else {
      goal.hidden = true;
    }

    var html = [], startYear = Math.floor(start / 12), y0 = start % 12;
    for (var m = 0; m < base.months; m++) {
      var yearIdx = Math.floor((y0 + m) / 12);
      var isYearEnd = (y0 + m) % 12 === 11 || m === base.months - 1;
      if (isYearEnd) {
        var bb = base.balances[m], pb = m < plan.months ? plan.balances[m] : 0;
        html.push('<tr><td>' + (startYear + yearIdx) + '</td><td>' + money.format(bb) + '</td><td>' + money.format(pb) +
          '</td><td>' + money.format(bb - pb) + '</td></tr>');
      }
    }
    el('mpYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
